#!/usr/bin/env python3
"""Regenerate ground truth for CSX-018_Q1 from local event data."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


TASK_ID = "CSX-018_Q1"
EVENT_ID = "CSX-018"
TARGET_FAMILY = "west_africa_day_night_heat_persistence_diagnosis"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_March-April_2024_West_Africa_and_Sahel_humid_heat_wave.json",
    "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive.json",
]

RUBRIC = [
    {
        "name": "Required JSON diagnosis",
        "points": 3,
        "description": "Returns exactly the requested compact JSON fields: event_days, hot_day_count_tmax_ge_40c, hdd40_c_days, hottest_3day_mean_tmax_c, warm_night_count_tmin_ge_27c, apparent_peak_lead_days, and classification.",
        "partial_credit": "Award 1-2 points if the answer has the right intent but omits one or two fields, uses unclear field names, or adds distracting narrative fields.",
    },
    {
        "name": "Day-night persistence counts",
        "points": 4,
        "description": "Computes the 5-day window, all five daily Tmax values at or above 40 C, and all five nightly Tmin values at or above 27 C.",
        "partial_credit": "Award 2-3 points for correct hot-day or warm-night counts with one missing count or minor threshold wording error; award 1 point for naming the event window only.",
    },
    {
        "name": "Heat-load arithmetic",
        "points": 4,
        "description": "Applies sum(max(Tmax - 40, 0)) across the event window and reports 15.1 C-days within 0.1 C-days.",
        "partial_credit": "Award 2-3 points for the correct formula with a small arithmetic or rounding error; award 1 point for using only peak temperature.",
    },
    {
        "name": "Peak three-day window",
        "points": 3,
        "description": "Computes rolling three-day Tmax means and reports the hottest mean as 43.6 C within 0.1 C.",
        "partial_credit": "Award 1-2 points for a correct rolling-window method with a small numeric error or for reporting the right peak days without the mean.",
    },
    {
        "name": "Apparent-temperature timing",
        "points": 2,
        "description": "Identifies the daily apparent-temperature peak on 2024-04-02 and the dry-bulb Tmax peak on 2024-04-03, giving a 1-day lead.",
        "partial_credit": "Award 1 point for naming one of the two peak dates or noting that apparent-temperature timing differs from dry-bulb timing.",
    },
    {
        "name": "Classification rule",
        "points": 3,
        "description": "Applies the stated rule and returns persistent_day_night_heat_load because all three threshold checks pass.",
        "partial_credit": "Award 1-2 points for a broadly correct persistent heat-load label without showing all required threshold checks.",
    },
    {
        "name": "Computed scope",
        "points": 1,
        "description": "Keeps the answer limited to computed heat-load evidence.",
        "partial_credit": "Award 0 points if the answer shifts into a broad event essay or adds unneeded planning guidance.",
    },
]


def package_root() -> Path:
    repo_root = Path(__file__).resolve().parents[3]
    return repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(root: Path, rel_path: str) -> dict[str, Any]:
    return json.loads((root / rel_path).read_text(encoding="utf-8-sig"))


def rolling_mean(values: list[float], window: int) -> tuple[float, int]:
    if len(values) < window:
        raise ValueError("rolling window is longer than the value list")
    means = [
        sum(values[index : index + window]) / window
        for index in range(len(values) - window + 1)
    ]
    best = max(means)
    return best, means.index(best)


def heat_degree_days(values: list[float], threshold: float) -> float:
    return sum(max(value - threshold, 0.0) for value in values)


def build_ground_truth() -> dict[str, Any]:
    root = package_root()
    event_meta = read_json(root, SOURCE_FILES[0])
    anchor = read_json(root, SOURCE_FILES[1])
    heat = read_json(root, SOURCE_FILES[2])

    dates = list(heat["daily"]["time"])
    tmax = [float(value) for value in heat["daily"]["temperature_2m_max"]]
    tmin = [float(value) for value in heat["daily"]["temperature_2m_min"]]
    apparent = [float(value) for value in heat["daily"]["apparent_temperature_max"]]

    event_days = len(dates)
    hot_day_count = sum(value >= 40.0 for value in tmax)
    warm_night_count = sum(value >= 27.0 for value in tmin)
    hdd40 = round(heat_degree_days(tmax, 40.0), 1)
    hottest_3day_mean, hottest_3day_start_index = rolling_mean(tmax, 3)
    hottest_3day_mean = round(hottest_3day_mean, 1)

    dry_peak_index = tmax.index(max(tmax))
    apparent_peak_index = apparent.index(max(apparent))
    apparent_peak_lead_days = dry_peak_index - apparent_peak_index

    classification = (
        "persistent_day_night_heat_load"
        if hot_day_count == event_days and warm_night_count == event_days and hdd40 > 10.0
        else "single_peak_or_incomplete_heat_load"
    )

    answer = {
        "event_days": event_days,
        "hot_day_count_tmax_ge_40c": hot_day_count,
        "hdd40_c_days": hdd40,
        "hottest_3day_mean_tmax_c": hottest_3day_mean,
        "warm_night_count_tmin_ge_27c": warm_night_count,
        "apparent_peak_lead_days": apparent_peak_lead_days,
        "classification": classification,
    }

    classification_rule = "persistent label requires all days Tmax>=40C, all nights Tmin>=27C, and hdd40>10C-days"

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "target_family": TARGET_FAMILY,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": answer,
        "key_values": {
            "event_name": event_meta["event_name"],
            "hazard_family": event_meta["hazard_family"],
            "event_window": {
                "start_date": anchor["temporal_window"]["start_date"],
                "end_date": anchor["temporal_window"]["end_date"],
                "dates": dates,
            },
            "daily_tmax_c": [round(value, 1) for value in tmax],
            "daily_tmin_c": [round(value, 1) for value in tmin],
            "daily_apparent_tmax_c": [round(value, 1) for value in apparent],
            "hottest_3day_window": {
                "start_date": dates[hottest_3day_start_index],
                "end_date": dates[hottest_3day_start_index + 2],
                "mean_tmax_c": hottest_3day_mean,
            },
            "dry_bulb_tmax_peak": {
                "date": dates[dry_peak_index],
                "tmax_c": round(tmax[dry_peak_index], 1),
            },
            "apparent_tmax_peak": {
                "date": dates[apparent_peak_index],
                "apparent_tmax_c": round(apparent[apparent_peak_index], 1),
            },
        },
        "decision_rule": {
            "formula_hdd40": "sum(max(Tmax - 40, 0))",
            "formula_hottest_3day_mean": "max rolling 3-day mean of daily Tmax",
            "classification_rule": classification_rule,
        },
        "rubric": {
            "total_points": 20,
            "criteria": RUBRIC,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }

def main() -> None:
    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    computed_gt = build_ground_truth()
    output_path.write_text(
        json.dumps(computed_gt, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
